from pathlib import Path
from fractions import Fraction as Q
import json,hashlib,itertools as it,ast,resource,time,sys
sys.path.insert(0,'code')
from classification_cubic_scroll_abelian_review import add,scale,mul,diff,parse,monomials
from classification_cubic_scroll_four_sources_review import substitute
begun=time.monotonic();resource.setrlimit(resource.RLIMIT_CPU,(110,115));resource.setrlimit(resource.RLIMIT_AS,(2048*1024**2,)*2)
job=json.load(open('research/classification/jobs/plane_m4_six_whole_separate_review.json'))
for z in job['exact_inputs_and_hashes']:assert hashlib.sha256(Path(z['path']).read_bytes()).hexdigest()==z['sha256'],z['path']
COUNT=0
def ck(a,b,label):
 global COUNT
 assert a==b,label
 COUNT+=1
coords=['a','b','c','u','v'];pairs=list(it.combinations(range(5),2));mons=monomials(5,2);COLS=[(ij,e)for ij in pairs for e in mons]
def atom(np,i=None,c=1):
 e=[0]*(np+5)
 if i is not None:e[i]=1
 return {tuple(e):Q(c)}if c else{}
def pmatrix():return [[{}for j in range(5)]for i in range(5)]
def put(P,i,j,v):P[i][j]=v;P[j][i]=scale(v,-1)
def tensor150(vals,np):
 P=pmatrix()
 for ((i,j),e),co in zip(COLS,vals):
  if Q(co):P[i][j]=add(P[i][j],{(0,)*np+e:Q(co)})
 for i,j in pairs:P[j][i]=scale(P[i][j],-1)
 return P
def mm(A,B):
 n=len(B[0])if B else 0
 return [[sum((x*B[k][j]for k,x in enumerate(row)if x),Q())for j in range(n)]for row in A]
def trans(A):return list(map(list,zip(*A)))
def mat(A):return [[Q(x)for x in row]for row in A]
def identity(n):return [[Q(i==j)for j in range(n)]for i in range(n)]
def wpart(P,k,np):
 out=pmatrix()
 for i,j in pairs:put(out,i,j,{e:c for e,c in P[i][j].items()if e[-2]+e[-1]-(i>=3)-(j>=3)==k})
 return out
def coeff(p,phys,np):return {e[:np]+(0,)*5:c for e,c in p.items()if e[np:]==phys}
def canonical1(P,np):
 X=[atom(np,np+i)for i in range(5)];Y=[{}for _ in range(5)]
 for i in range(3):Y[i]=scale(add(mul(coeff(P[i][3],(0,0,0,2,0),np),X[3]),mul(coeff(P[i][4],(0,0,0,0,2),np),X[4])),-1)
 out=pmatrix()
 for i,j in pairs:put(out,i,j,add(P[i][j],scale(mul(X[i],Y[j]),-1),mul(X[j],Y[i])))
 return out
B1=[]
for normal in (3,4):
 for ij in it.combinations(range(3),2):
  for k in range(3):
   e=[0]*5;e[normal]+=1;e[k]+=1;B1.append((ij,tuple(e)))
for normal,ex in [(3,(3,4)),(3,(4,4)),(4,(3,3)),(4,(3,4))]:
 for i in range(3):
  e=[0]*5
  for k in ex:e[k]+=1
  B1.append(((i,normal),tuple(e)))
B2=[]
for ij in it.combinations(range(3),2):
 for ex in [(3,3),(3,4),(4,4)]:
  e=[0]*5
  for k in ex:e[k]+=1
  B2.append((ij,tuple(e)))
def basisvectors(B):return [[Q(ij==jj and e==f)for jj,f in COLS]for ij,e in B]
def decodebasis(B,values,np):
 P=pmatrix()
 for ((i,j),e),p in zip(B,values):P[i][j]=add(P[i][j],mul(p,{(0,)*np+e:Q(1)}))
 for i,j in pairs:P[j][i]=scale(P[i][j],-1)
 return P
def coordinates1(P,np):
 vals=[coeff(P[i][j],e,np)for(i,j),e in B1]
 ck(decodebasis(B1,vals,np),P,'complete raw30 afterEuler exact reconstruction')
 return vals
def push(P,s,np):
 n=np+5;old=[atom(np,np+i)for i in range(5)]
 for i in range(3):old[i]=add(old[i],scale(mul(s[2*i],old[3]),-1),scale(mul(s[2*i+1],old[4]),-1))
 images=[atom(np,i)for i in range(np)]+old
 sub=[[substitute(P[i][j],images,n)for j in range(5)]for i in range(5)]
 G=[[atom(np,c=int(i==j))for j in range(5)]for i in range(5)]
 for i in range(3):G[i][3],G[i][4]=s[2*i],s[2*i+1]
 out=pmatrix()
 for i,j in pairs:put(out,i,j,add(*(mul(mul(G[i][k],sub[k][ell]),G[j][ell])for k in range(5)for ell in range(5)if G[i][k]and G[j][ell])))
 return out
def jac(P,np):
 strict={}
 for tri in it.combinations(range(5),3):strict[tri]=add(*(mul(P[i][ell],diff(P[j][k],np+ell))for i,j,k in [tri,(tri[1],tri[2],tri[0]),(tri[2],tri[0],tri[1])]for ell in range(5)))
 return [add(*(scale(mul(atom(np,np+quad[i]),strict[quad[:i]+quad[i+1:]]),(-1)**i)for i in range(4)))for quad in it.combinations(range(5),4)]
def actual(P,np):
 D={}
 for omit in range(5):
  i,j,k,l=[v for v in range(5)if v!=omit]
  pf=add(mul(P[i][j],P[k][l]),scale(mul(P[i][k],P[j][l]),-1),mul(P[i][l],P[j][k]))
  D=add(D,scale(mul(atom(np,np+omit),pf),(-1)**omit))
 return D
oldspecial=json.load(open('reports/CLASSIFICATION_PLANE_REDUCIBLE_CUBIC_M4_SPECIAL_20261107.json'));oldrepeat=json.load(open('reports/CLASSIFICATION_PLANE_M4_REPEATED_211_20261107.json'));new=json.load(open('reports/CLASSIFICATION_PLANE_M4_SIX_WHOLE_SHEAR_FACTORS_20261108.json'))
ck(mat(oldspecial['full30_weight1_basis']),basisvectors(B1),'old complete30 basis');ck(mat(oldspecial['full9_weight2_basis']),basisvectors(B2),'old FULL9 basis')
results=[]
for saved in new['cases']:
 typ=saved['type'];old=next(c for p in [oldspecial,oldrepeat]for c in p['cases']if c['type']==typ)
 if 'full30_weight1_basis'in old:ck(mat(old['full30_weight1_basis']),basisvectors(B1),'repeat same30 basis');ck(mat(old['full9_weight2_basis']),basisvectors(B2),'repeat same9 basis')
 K=trans(mat(old['full30_weight1_kernel']));assert len(K)==30 and len(K[0])==6
 C=mat(saved['full_shear_to_K1_matrix']);Ci=mat(saved['global_inverse_K1_to_shear']);ck(mm(C,Ci),identity(6),'global C inverse1');ck(mm(Ci,C),identity(6),'global C inverse2')
 P0=tensor150(old['full150_P0'],0);unitcols=[]
 for at in range(6):
  shear=[atom(0,c=int(i==at))for i in range(6)]
  values=coordinates1(canonical1(wpart(push(P0,shear,0),1,0),0),0)
  unitcols.append([v.get((0,)*5,Q())for v in values]);assert all(set(v)<={(0,)*5}for v in values)
 S=trans(unitcols);ck(S,mat(saved['shear_30_by6']),'full unit shear S');ck(S,mm(K,C),'S equals K C')
 # ALL alpha6/rawP2nine simultaneously; not unit-shear transitivity extrapolation.
 np=15;an=[f'A{i}'for i in range(6)];rn=[f'R{i}'for i in range(9)];names=an+rn+coords
 alpha=[atom(np,i)for i in range(6)];rs=[atom(np,6+i)for i in range(9)]
 p1vals=[add(*(scale(alpha[j],K[i][j])for j in range(6)))for i in range(30)]
 P0all=tensor150(old['full150_P0'],np);P1=decodebasis(B1,p1vals,np);P2=decodebasis(B2,rs,np)
 raw=[[add(P0all[i][j],P1[i][j],P2[i][j])for j in range(5)]for i in range(5)]
 s=[scale(add(*(scale(alpha[j],Ci[i][j])for j in range(6))),-1)for i in range(6)]
 changed=push(raw,s,np);ck(wpart(changed,0,np),P0all,'actual fullshear P0 unchanged')
 can=canonical1(wpart(changed,1,np),np);ck(can,pmatrix(),'ALLalpha actual inverse shear kills whole P1 moduloEuler')
 rem=wpart(changed,2,np);newrs=[coeff(rem[i][j],ex,np)for(i,j),ex in B2];ck(decodebasis(B2,newrs,np),rem,'FULL9P2 stays FULL9 afteractualshear')
 shifts=[add(x,scale(y,-1))for x,y in zip(newrs,rs)]
 assert all(not any(ex[6:15])for p in shifts for ex in p)
 # Remaining source map is triangular rnew=r+shift(alpha), hence has literal polynomial inverse.
 L=mat(old['full350_weight2_matrix'])+mat(old.get('all13_leading_shape_weight2_rows',old.get('all_leading_shape_weight2_rows')))
 ck(len(L),saved['weight2_complete_matrix_rows'],'complete old L rowcount')
 cert=old.get('full_weight2_rank_certificate',old.get('weight2_rank_certificate'))
 KL=mat(saved['normalized_P2_kernel_9_by_n']);n=9-cert['rank'];assert n==len(saved['normalized_P2_parameter_names'])
 ck(mm(L,KL),[[]if n==0 else[Q()for _ in range(n)]for _ in L],'whole oldL times normalizedkernel')
 free=[j for j in range(9)if j not in cert['columns']];ck([KL[j]for j in free],identity(n),'normalizedkernel full independent freecoordinates')
 np=n;names=saved['normalized_P2_parameter_names']+coords;t=[atom(np,i)for i in range(n)]
 vals=[add(*(scale(t[j],KL[i][j])for j in range(n)))for i in range(9)];norm2=decodebasis(B2,vals,np);norm0=tensor150(old['full150_P0'],np);norm=[[add(norm0[i][j],norm2[i][j])for j in range(5)]for i in range(5)]
 for i,j in pairs:ck(norm[i][j],parse(saved['normalized_full_brackets'][str((i,j))],names),'all150 normalized fullsource')
 for p in jac(norm,np):ck(p,{},'all350 normalized originalJac')
 D=actual(norm,np);ck(D,parse(saved['actual_quintic'],names),'whole actualPf/D')
 if saved['proper_factor_or_zero']=='0':ck(D,{},'D identicallyzero')
 else:
  factor=parse(saved['proper_factor_or_zero'],names);quotient=parse(saved['exact_factor_quotient'],names);ck(D,mul(factor,quotient),'full actualD factor identity');assert factor and {sum(ex[np:])for ex in factor}=={sum(next(iter(factor))[np:])}and 0<sum(next(iter(factor))[np:])<5
 assert all(ex[-2]+ex[-1]==4 for ex in D)
 results.append({'type':typ,'all_constant_C_inverse_and_S_equals_KC':True,'unit_pushes_reconstructed':True,'ALLalpha6_and_FULLrawP2nine_actual_inverse_shear_verified':True,'P0_fixed_and_P1_zero_modEuler':True,'global_P2_inverse_triangular_shifts_sparse':[{','.join(map(str,e[:6])):str(co)for e,co in p.items()}for p in shifts],'no_source_parameter_inversion':True,'whole_normalized_P2_kernel_dimension':n,'old_completeL_kernel_annihilation_and_independence':True,'all150_normalized_tensor_and_all350_Jacobi':True,'full_actualPf_factor_identity':True,'whole_irreducible_quintic_empty':True})
result={'task_id':'E_reduced_nonnormal','all_passed':True,'scope':'Allsix specified reducedR m4 fixedsources areirreduciblequinticempty; wholem4 aggregation requiresseparate acceptedotherbranches','cases':results,'new_component_count':0,'no_new_M1_rank_kernel_point_profile_or_GB':True,'no_producer_or_CAS_import':True,'identity_count':COUNT,'input_sha256':{p['path']:hashlib.sha256(Path(p['path']).read_bytes()).hexdigest()for p in job['exact_inputs_and_hashes']},'inline_source':job['inline_source'],'seconds':time.monotonic()-begun,'maxrss_kb':resource.getrusage(resource.RUSAGE_SELF).ru_maxrss}
out=Path('reports/CLASSIFICATION_PLANE_M4_SIX_WHOLE_SEPARATE_REVIEW_20261108.json')
with out.open('x')as f:json.dump(result,f,indent=2);f.write('\n')
print(json.dumps({k:result[k]for k in ['all_passed','identity_count','seconds','maxrss_kb']}))
